ee:message.ee:set-payload:
%dw 2.0
output application/json
---
vars.inputPayload ++ {
  addonPackage: (vars.inputPayload.addonPackage default []) map ((item) -> item ++ { actionCode: "ADD" })
}

%dw 2.0
output application/json
---
{
	"status": 404,
	"code": "NOT_FOUND",
	"message": {
		"message": "Data not found"
	},
	"messageServer": "",
	"cause": [{
		"origin": app.name,
		"message": "org.mule.extension.http.api.request.validator.NotFoundException"
	}]
}

%dw 2.0
output application/json
---
{
	"status": 500,
	"code": "",
