	    "origin": app.name,
	    "message": "org.mule.extension.http.api.request.validator.ResponseValidatorTypedException"
	  }
	]
}

when.expression:
#[%dw 2.0
output application/json
var fechaActual = now() >> "America/Bogota" as String {format: "uuuu-MM-dd"}
var fechaActivacion = vars.dataValPromo.fechaActivacion as String {format: "uuuu-MM-dd"}
var promoByCondition = (vars.promociones default []) groupBy ((item, index) -> item.Condicion)
---
(upper(vars.dataValPromo.condicion) == p('global.condicionPortado')) and 
((((fechaActual - fechaActivacion) as Number {unit: "days"}) < promoByCondition."Usuario Portado"[0].Vigencia)) and
(fechaActual <= (promoByCondition."Usuario Portado"[0].Fecha_Fin as Date {format: "dd/MM/yyyy"})) and 
(fechaActual >= (promoByCondition."Usuario Portado"[0].Fecha_Inicio as Date {format: "dd/MM/yyyy"}))]

ee:variables.ee:set-variable:
%dw 2.0
import * from dw::util::Values
output application/json
var promoByCondition = vars.promociones groupBy ((item, index) -> item.Condicion)
var promoXpkgByCampId = vars.promXpkg filter ((item, index) -> item."CampañaId" == promoByCondition."Usuario Nuevo"[0]."_id")
var mappedStrings = vars.adds map ((pkg) ->
    if (promoXpkgByCampId.Paquete_Seleccionado contains pkg.packageId)
        "Paquete recibido: " ++ pkg.packageId ++ " Paquete aplicado: " ++ (vars.promXpkg filter ((item, index) -> item.Paquete_Seleccionado == pkg.packageId)).Paquete_Entregar[0]
    else
        ""
)
---
(mappedStrings filter ((item, index) -> !isEmpty(item))) joinBy ", "

%dw 2.0
import * from dw::util::Values
output application/json
var promoByCondition = vars.promociones groupBy ((item, index) -> item.Condicion)
var promoXpkgByCampId = vars.promXpkg filter ((item, index) -> item."CampañaId" == promoByCondition."Usuario Portado"[0]."_id")
---
vars.adds map ((pkg) ->
    if (promoXpkgByCampId.Paquete_Seleccionado contains pkg.packageId)
        pkg update "packageId" with (vars.promXpkg filter ((item, index) -> item.Paquete_Seleccionado == pkg.packageId)).Paquete_Entregar[0]
    else
        pkg
)

%dw 2.0
import * from dw::util::Values
output application/json
var promoByCondition = vars.promociones groupBy ((item, index) -> item.Condicion)
var promoXpkgByCampId = vars.promXpkg filter ((item, index) -> item."CampañaId" == promoByCondition."Usuario Portado"[0]."_id")
---
{
    "Fecha_aprovision": now() >> "America/Bogota",
    "IntegrationId": vars.connectionNumber,
    "packages": ((vars.adds map ((pkg) ->
        if (promoXpkgByCampId.Paquete_Seleccionado contains pkg.packageId)
        {
            "Paquete_recibido": pkg.packageId,
            "Paquete_aplicado": (vars.promXpkg filter ((item, index) -> item.Paquete_Seleccionado == pkg.packageId)).Paquete_Entregar[0]
        }
        else
            {}
    )) filter ((item, index) -> !isEmpty(item)))
}

when.expression:
#[%dw 2.0
output application/json
var fechaActual = now() >> "America/Bogota" as String {format: "uuuu-MM-dd"}
var fechaActivacion = vars.dataValPromo.fechaActivacion as String {format: "uuuu-MM-dd"}
var promoByCondition = (vars.promociones default []) groupBy ((item, index) -> item.Condicion)
---
(upper(vars.dataValPromo.condicion) == p('global.condicionNuevo')) and 
((((fechaActual - fechaActivacion) as Number {unit: "days"}) < promoByCondition."Usuario Nuevo"[0].Vigencia)) and
(fechaActual <= (promoByCondition."Usuario Nuevo"[0].Fecha_Fin as Date {format: "dd/MM/yyyy"})) and 
(fechaActual >= (promoByCondition."Usuario Nuevo"[0].Fecha_Inicio as Date {format: "dd/MM/yyyy"}))]

